export default class YouTube {
    constructor(el) {  
        this.el = el;
        this.videoContainer = this.el.querySelector('.js-video');
        this.poster = this.el.querySelector('.js-poster');
        this.videoId = this.el.dataset.videoId;
        this.playerReady = false;

        YouTube.instances.push(this);

        this.options = {
            autoplay: this.poster ? 1 : 0,
            controls: ('noControls' in this.el.dataset) ? 0 : 1,
        };

        if (this.videoId) {
            YouTube.loadScript();
        } else {
            console.error(`Video ID required for ${this.el}`);
        }
    }

    static loadScript() {
        if (!YouTube.scriptIsLoading) {
            YouTube.scriptIsLoading = true;
            const script = document.createElement('script');
            script.src = 'https://www.youtube.com/iframe_api';
            document.body.appendChild(script);
        }
    }

    init() {
        document.documentElement.classList.add('is-video-ready');

        this.initPlayer = this.initPlayer.bind(this);

        if (this.poster) {
            this.poster.addEventListener('click', this.initPlayer);
        } else {
            this.initPlayer();
        }
    }
    
    initPlayer(e) {
        if (e) {
            this.poster.removeEventListener('click', this.initPlayer);
        }

        this.player = new YT.Player(this.videoContainer, {
            height: '100%',
            width: '100%',
            videoId: this.videoId,
            playerVars: {
                rel: 0,
                autoplay: this.options.autoplay,
                controls: this.options.controls,
            },
            events: {
                onReady: () => {
                    this.playerReady = true;
                    const observer = new IntersectionObserver(this.watch.bind(this), { rootMargin: '0px 0px 0px 0px'});
                    observer.observe(this.el);
                },
                onStateChange: (e) => {
                    if (e.data == YT.PlayerState.PLAYING) {
                        YouTube.pauseAll(this);
                    } else if (e.data == YT.PlayerState.ENDED) {
                        this.player.seekTo(0);
                        this.player.stopVideo();
                    }

                }
            }
        });
    }

    watch(entries) {
        if (this.playerReady && !entries[0].isIntersecting) {
            this.player.pauseVideo();
        }
    }

    static initAll() {
        for (let i = 0; i < YouTube.instances.length; i++) {
            YouTube.instances[i].init();
        }
    }

    static pauseAll(current) {
        for (let i = 0; i < YouTube.instances.length; i++) {
            const instance = YouTube.instances[i];
            if (instance.playerReady && instance !== current) {
                instance.player.pauseVideo();
            }
        }
    }
}

YouTube.instances = [];
window.onYouTubeIframeAPIReady = YouTube.initAll;



