import ComponentFactory from "./ComponentFactory.js";
import ActiveSection from './components/ActiveSection.js';
import { initShaderCanvases } from "./components/ShaderCanvas.js";
// import Icons from "./utils/Icons.js";

class Main {
  constructor() {
    this.init();
  }

  init() {
    document.documentElement.classList.add("has-js");

    new ComponentFactory();
    new ActiveSection();
    initShaderCanvases();

    // Icons.load();
  }
}

window.addEventListener("load", () => {
    new Main();
});